import numpy as np

def true_f(t):
    return (4 + 2.5 * np.cos(2 * np.pi * t / 8.5)
            + 0.8 * np.sin(4 * np.pi * t / 8.5))

def make_train(rng, n=30):
    t = rng.uniform(0, 8.5, n)
    y = true_f(t) + rng.normal(0, 0.6, n)
    return t, y

def poly_fit(degree):
    def fit_fn(t, y, x0):
        coef = np.polyfit(t / 4.25 - 1, y, degree)
        return np.polyval(coef, x0 / 4.25 - 1)
    return fit_fn

def decompose(true_f, preds, noise_var):
    preds = np.asarray(preds, float)
    bias2 = (preds.mean() - true_f) ** 2
    var = preds.var()
    total = bias2 + var + noise_var
    return round(float(bias2), 4), round(float(var), 4), round(float(total), 4)
